import React, { useState } from "react";

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState("home");

  const tabs = [
    { key: "home", label: "Accueil" },
    { key: "companies", label: "Mes Entreprises" },
    { key: "domains", label: "Domaines d’intervention" },
    { key: "alerts", label: "Publications & Alertes" },
    { key: "stats", label: "Statistiques" },
    { key: "settings", label: "Paramètres" },
  ];

  return (
    <div className="flex h-screen bg-[#F5F6F8]">
      {/* Sidebar */}
      <aside className="w-64 bg-[#003865] text-white flex flex-col p-4">
        <h2 className="text-2xl font-bold mb-8">Veille Marchés</h2>
        <nav className="flex flex-col space-y-2">
          {tabs.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`text-left px-3 py-2 rounded ${
                activeTab === tab.key
                  ? "bg-[#EF5B0C] text-white"
                  : "hover:bg-[#004C8C]"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-6 overflow-y-auto">
        <header className="mb-6 bg-gradient-to-r from-[#003865] to-[#EF5B0C] text-white px-6 py-4 rounded shadow">
          <h1 className="text-xl font-semibold">
            {tabs.find((tab) => tab.key === activeTab)?.label}
          </h1>
        </header>

        <section>
          {activeTab === "home" && <HomeSection />}
          {activeTab === "companies" && <CompaniesSection />}
          {activeTab === "domains" && <DomainsSection />}
          {activeTab === "alerts" && <AlertsSection />}
          {activeTab === "stats" && <StatsSection />}
          {activeTab === "settings" && <SettingsSection />}
        </section>
      </main>
    </div>
  );
};

// Example placeholders
const HomeSection = () => (
  <div>
    <p className="text-[#003865]">Bienvenue sur votre tableau de bord.</p>
    <p className="text-sm text-[#6b6b6b]">
      Vous pouvez gérer vos entreprises, alertes et préférences ici.
    </p>
  </div>
);

const CompaniesSection = () => (
  <div>
    <h2 className="text-lg font-semibold text-[#003865] mb-2">
      Mes Entreprises
    </h2>
    <button className="bg-[#EF5B0C] text-white px-4 py-2 rounded mb-4">
      Ajouter une entreprise
    </button>
    {/* Placeholder: Liste des entreprises */}
    <div className="bg-white p-4 rounded shadow text-[#003865]">
      Liste à venir…
    </div>
  </div>
);

const DomainsSection = () => (
  <div>
    <h2 className="text-lg font-semibold text-[#003865] mb-2">
      Domaines d’intervention
    </h2>
    <p className="text-[#6b6b6b]">
      Modifier ou attribuer les domaines pour chaque entreprise.
    </p>
  </div>
);

const AlertsSection = () => (
  <div>
    <h2 className="text-lg font-semibold text-[#003865] mb-2">
      Publications & Alertes
    </h2>
    <p className="text-[#6b6b6b]">
      Consultez vos alertes et les publications pertinentes.
    </p>
  </div>
);

const StatsSection = () => (
  <div>
    <h2 className="text-lg font-semibold text-[#003865] mb-2">Statistiques</h2>
    <p className="text-[#6b6b6b]">
      Nombre d’alertes, publications reçues, répartition par entreprise…
    </p>
  </div>
);

const SettingsSection = () => (
  <div>
    <h2 className="text-lg font-semibold text-[#003865] mb-2">Paramètres</h2>
    <p className="text-[#6b6b6b]">
      Modifier votre profil, mot de passe, ou préférences globales.
    </p>
  </div>
);

export default Dashboard;
